#!/usr/bin/env bash
# _dracut-cross-lib.sh — SOURCED helper for the ARM cross-dracut initramfs path.
#
# WHY THIS EXISTS
# An --encrypt-root ARM installer (rpi5/frite/orangepi5/orangepi-zero2/
# orangepi-zero2w/orangepi-zero3, and
# jetson once it gains a split boot partition) needs a *disk-boot* initramfs
# that carries the `crypt` dracut module so the firmware-loaded boot stage can
# unlock the LUKS2 root. That initramfs is arm64, but the builder runs on an
# amd64 host, so it is generated by chrooting INTO the target sysroot and running
# the sysroot's own /usr/bin/dracut under a static qemu-aarch64 user emulator
# (Strategy 1 / "qemu-chroot" in each board's build_disk_initramfs()). That is
# the ONLY strategy that actually emits a correct arm64 initramfs — the host-sh
# and host-dracut fallbacks cannot (host dracut is amd64; the sysroot dracut run
# under the host /bin/sh has been observed to fail on a minimal cross sysroot).
#
# Strategy 1's guard is `grep ^interpreter /proc/sys/fs/binfmt_misc/qemu-aarch64`
# plus `-x` on that interpreter. In a fresh builder container that guard returns
# empty for TWO reasons, both fixed around this library:
#   (a) the builder image did not ship a qemu-aarch64 user emulator at all
#       (fixed in Dockerfile.build FINAL stage: emerge app-emulation/qemu with
#        static-user + QEMU_USER_TARGETS=aarch64 -> /usr/bin/qemu-aarch64).
#   (b) binfmt_misc is a kernel-GLOBAL subsystem: a registration written during
#       `docker build` does NOT survive into a fresh `docker run` container, so
#       it must be (re)done at RUN time inside the (privileged) run container.
#       dracut_cross_register_qemu() does that, idempotently and non-fatally.
#
# This library factors ONLY the shared, load-bearing bits that were otherwise
# copy-pasted (and would drift) across the board scripts:
#   * the qemu-aarch64 binfmt_misc mount + registration, and
#   * the availability predicate the fail-fast preflight evaluates.
# The per-board build_disk_initramfs()/build_live_initramfs() BODY stays in each
# script because it references genuinely board-specific state (SYSROOT vs
# BOOT_STAGE staging, distinct RETURN-trap umount helpers, board KVER vars).
# Fully unifying build_disk_initramfs() is a larger, higher-risk follow-up.
#
# Following scripts/_download-lib.sh's precedent, this file is meant to be
# SOURCED, never executed:
#     source "$(dirname "${BASH_SOURCE[0]}")/_dracut-cross-lib.sh"
# It does NOT set shell options — the sourcing script owns `set -euo pipefail`.
# It defines functions + constants only (no top-level side effects beyond the
# double-source guard below), so sourcing it is safe and idempotent.
#
# Public API:
#   dracut_cross_register_qemu
#       — Idempotent, NON-FATAL. If /proc/sys/fs/binfmt_misc/qemu-aarch64 is
#         already registered, no-op. Otherwise mount binfmt_misc if needed and
#         register the aarch64 interpreter (preferring a qemu-shipped binfmt.d
#         conf, else the pinned literal line). Every step is `|| true`/warn, so
#         a non-encrypt or unprivileged build never aborts on it. Always
#         returns 0.
#
#   dracut_cross_preflight_ok
#       — Predicate (return 0/1, no output) for the fail-fast preflight:
#         qemu-aarch64 is registered in binfmt_misc AND its ^interpreter path is
#         `-x` on the host. Does NOT check the sysroot's own dracut — that is
#         emerged later in @stage4 and asserted separately just before
#         build_disk_initramfs; this predicate's job is the qemu/binfmt half
#         that is otherwise only discovered hours into the build.
#
#   dracut_cross_qemu_interp
#       — Echo the aarch64 interpreter path: the registered ^interpreter if a
#         registration exists, else the pinned default. Used for log messages
#         and by the predicate.

# Guard against double-sourcing. `return` only works when sourced; fall back to
# `exit` if someone runs the file directly.
# shellcheck disable=SC2317
if [ -n "${_DRACUT_CROSS_LIB_SOURCED:-}" ]; then
    return 0 2>/dev/null || exit 0
fi
_DRACUT_CROSS_LIB_SOURCED=1

# Host-safety guard. dracut_cross_register_qemu() mounts binfmt_misc and writes a
# registration, and binfmt_misc is KERNEL-GLOBAL (see the (b) note above) — on a
# native root build that mutates the OPERATOR'S kernel and mount namespace, not a
# disposable container. Sourced here (idempotent, no side effects) so the guard
# travels with this library rather than depending on each of the 5 ARM builders
# remembering to source it first.
# shellcheck source=scripts/_host-guard-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/_host-guard-lib.sh"

# ── Pinned constants (ONE audited copy) ────────────────────────────
# The binfmt_misc node the aarch64 registration appears at, and the interpreter
# path the host registers (matches the /usr/bin/qemu-aarch64 the Dockerfile.build
# FINAL stage now emerges as a STATIC binary).
DRACUT_CROSS_QEMU_ARCH="aarch64"
DRACUT_CROSS_BINFMT_NODE="/proc/sys/fs/binfmt_misc/qemu-aarch64"
DRACUT_CROSS_QEMU_INTERP="/usr/bin/qemu-aarch64"

# The exact registration line for a static qemu-aarch64, in binfmt_misc's
# `:name:type:offset:magic:mask:interpreter:flags` format. The magic/mask below
# were verified byte-for-byte against a host that already had qemu-aarch64
# registered (magic 7f454c46 0201010000000000 000002 00b700 ; the mask blanks the
# ELF ABI/pad byte 7 and the low bit of the machine field). The kernel parses the
# `\x..` escapes itself, so this must be written with a LITERAL backslash-x
# string (printf '%s', NOT echo -e). Flags OC: O = open the interpreter at
# registration/exec (needed so the interpreter is found relative to the chroot's
# view), C = credentials from the target binary.
# shellcheck disable=SC2016
DRACUT_CROSS_BINFMT_LINE=':qemu-aarch64:M::\x7f\x45\x4c\x46\x02\x01\x01\x00\x00\x00\x00\x00\x00\x00\x00\x00\x02\x00\xb7\x00:\xff\xff\xff\xff\xff\xff\xff\x00\xff\xff\xff\xff\xff\xff\xff\xff\xfe\xff\xff\xff:/usr/bin/qemu-aarch64:OC'

# ── Logging (self-contained; colour only on a TTY) ─────────────────
# Kept independent of the sourcing script's info/warn so the library is safe to
# source before those are defined (they are; this only matters for robustness).
if [ -t 2 ]; then
    _DXC_YEL=$'\033[33m'; _DXC_GRN=$'\033[32m'; _DXC_RST=$'\033[0m'
else
    _DXC_YEL=''; _DXC_GRN=''; _DXC_RST=''
fi
_dxc_warn() { printf '%s[cross-dracut] WARN:%s %s\n' "${_DXC_YEL}" "${_DXC_RST}" "$*" >&2; }
_dxc_info() { printf '%s[cross-dracut]%s %s\n'       "${_DXC_GRN}" "${_DXC_RST}" "$*" >&2; }

# dracut_cross_qemu_interp — echo the aarch64 interpreter path.
# Reads the live registration's ^interpreter if present; else the pinned default.
dracut_cross_qemu_interp() {
    local interp=""
    if [ -e "${DRACUT_CROSS_BINFMT_NODE}" ]; then
        interp="$(grep '^interpreter' "${DRACUT_CROSS_BINFMT_NODE}" 2>/dev/null | awk '{print $2}')"
    fi
    [ -n "${interp}" ] || interp="${DRACUT_CROSS_QEMU_INTERP}"
    printf '%s\n' "${interp}"
}

# dracut_cross_register_qemu — idempotent, non-fatal binfmt_misc mount+register.
# Always returns 0; the caller must never abort on it (a non-encrypt build, or an
# unprivileged container where mount/register are denied, must proceed).
# _dxc_report_existing — a qemu-aarch64 registration already exists (from this
# container, a prior run, or a HOST-side registration — binfmt_misc is
# KERNEL-GLOBAL, so mounting it inside a container exposes the host's entries).
# Without the F (fix-binary) flag the kernel opens the interpreter path in the
# EXECUTING process's mount namespace, so an inherited registration only helps
# if the interpreter also exists INSIDE this container. Stay quiet when it is
# usable (this runs on every build); WARN actionably when it is not.
_dxc_report_existing() {
    local hinterp
    hinterp="$(dracut_cross_qemu_interp)"
    if [ ! -x "${hinterp}" ]; then
        _dxc_warn "qemu-${DRACUT_CROSS_QEMU_ARCH} is already registered (kernel-global) -> ${hinterp}, but that interpreter is missing in THIS container — rebuild the builder image (make docker-image) so it ships the static qemu."
    fi
}

dracut_cross_register_qemu() {
    # Already registered (this or a prior container/run, or host-side with
    # binfmt_misc already mounted) — report honestly, nothing to write.
    if [ -e "${DRACUT_CROSS_BINFMT_NODE}" ]; then
        _dxc_report_existing
        return 0
    fi

    # HOST-MUTATION GATE. Everything below this point mounts a kernel filesystem
    # into the caller's mount namespace and writes a KERNEL-GLOBAL interpreter
    # registration. In the builder container that is required and disposable; on
    # the operator's machine it is a change to their running kernel that this
    # build has no business making. The already-registered fast path above stays
    # FIRST and unconditional, so a host that has qemu binfmt set up properly
    # (systemd-binfmt) satisfies us and the build proceeds — that IS "proceed if
    # the host already satisfies it". Stay NON-FATAL (contract: always return 0);
    # the callers' fail-fast preflights (jetson/rpi5) then report the real,
    # actionable problem at the right altitude.
    if ! hostguard_mutation_allowed; then
        _dxc_warn "qemu-${DRACUT_CROSS_QEMU_ARCH} is not registered and this is not a build container — refusing to mount binfmt_misc / write a KERNEL-GLOBAL registration on your system. Either: emerge app-emulation/qemu with static-user + QEMU_USER_TARGETS=aarch64 and enable systemd-binfmt (or app-emulation/qemu-binfmt), or run the build in the container (make docker-image)."
        return 0
    fi

    # binfmt_misc must be mounted before we can register. In a --privileged
    # container this succeeds; otherwise it is denied and we fall through
    # non-fatally (the preflight/late-refusal then reports the real problem).
    if ! mountpoint -q /proc/sys/fs/binfmt_misc 2>/dev/null; then
        mount -t binfmt_misc none /proc/sys/fs/binfmt_misc 2>/dev/null \
            || _dxc_warn "could not mount binfmt_misc (need a --privileged container); qemu-aarch64 will be unregistered."
    fi

    # The mount may have just made a HOST-side registration visible. Recognize
    # it here instead of falling through to a doomed EEXIST write — which used
    # to print a misleading "registration failed" WARN immediately followed by
    # a "registered" INFO for the very same entry.
    if [ -e "${DRACUT_CROSS_BINFMT_NODE}" ]; then
        _dxc_report_existing
        return 0
    fi

    local reg="/proc/sys/fs/binfmt_misc/register"
    if [ ! -w "${reg}" ]; then
        _dxc_warn "${reg} not writable; cannot register qemu-${DRACUT_CROSS_QEMU_ARCH}."
        return 0
    fi

    # Prefer a qemu-shipped binfmt.d conf if one is present (it carries the
    # exact magic/mask/interpreter the installed qemu expects). These files ARE
    # register lines (leading ':'); feed only those through.
    local conf line
    for conf in /usr/lib/binfmt.d/qemu-aarch64.conf \
                /usr/lib/binfmt.d/qemu-aarch64-static.conf \
                /etc/binfmt.d/qemu-aarch64.conf; do
        [ -r "${conf}" ] || continue
        while IFS= read -r line; do
            case "${line}" in
                :*) printf '%s\n' "${line}" > "${reg}" 2>/dev/null || true ;;
            esac
        done < "${conf}"
        [ -e "${DRACUT_CROSS_BINFMT_NODE}" ] && {
            _dxc_info "registered qemu-${DRACUT_CROSS_QEMU_ARCH} from ${conf}."
            return 0
        }
    done

    # Fall back to the pinned literal registration line. Re-check the node
    # before warning: a write can fail EEXIST because something else registered
    # the same name concurrently, which is a success for our purposes — never
    # print "failed" and "registered" for the same entry.
    if printf '%s\n' "${DRACUT_CROSS_BINFMT_LINE}" > "${reg}" 2>/dev/null; then
        _dxc_info "registered qemu-${DRACUT_CROSS_QEMU_ARCH} -> $(dracut_cross_qemu_interp)."
    elif [ -e "${DRACUT_CROSS_BINFMT_NODE}" ]; then
        _dxc_info "qemu-${DRACUT_CROSS_QEMU_ARCH} registered concurrently -> $(dracut_cross_qemu_interp)."
    else
        _dxc_warn "writing the qemu-${DRACUT_CROSS_QEMU_ARCH} registration failed."
    fi
    return 0
}

# dracut_cross_preflight_ok — predicate: qemu-aarch64 registered AND interp -x.
# Returns 0 (usable) or 1 (not). Produces no stdout.
dracut_cross_preflight_ok() {
    [ -e "${DRACUT_CROSS_BINFMT_NODE}" ] || return 1
    local interp
    interp="$(dracut_cross_qemu_interp)"
    [ -n "${interp}" ] && [ -x "${interp}" ]
}

# ── Target-exec package family ─────────────────────────────────────
# waf-configured packages EXECUTE cross-built test binaries at configure time
# via the binfmt qemu interpreter ("Checking uname machine type: not found /
# Checking simple C program: not found -> The configuration failed"). When
# qemu-aarch64 is unusable in the build container they are KNOWN to fail
# ~40min into Phase 2 and then silently drop from the payload (surfacing much
# later as the payload-incomplete assert) — real jetson edge_ai failure,
# session 20260716-160638-f8c153 (tdb-1.4.15 + talloc-2.4.4 -> samba-4.24.4 +
# cifs-utils-7.7 dropped). EXACTLY the evidence-proven waf family is pinned
# here; sys-libs/tevent and dev-libs/ldb are same-family (waf) candidates but
# unproven in this codebase's package sets, so they are deliberately NOT
# listed — a missed atom degrades to today's late failure, never a false
# early block.
DRACUT_CROSS_TARGET_EXEC_ATOMS="sys-libs/tdb sys-libs/talloc net-fs/samba net-fs/cifs-utils"

# dracut_cross_target_exec_blockers — PURE filter for the fail-fast preflight:
# reads package atoms one per line on stdin and prints (one per line) the
# intersection with the pinned target-exec family above. No side effects;
# empty input or no match -> empty output, always returns 0.
dracut_cross_target_exec_blockers() {
    local _atom _fam
    while IFS= read -r _atom; do
        [ -n "${_atom}" ] || continue
        for _fam in ${DRACUT_CROSS_TARGET_EXEC_ATOMS}; do
            if [ "${_atom}" = "${_fam}" ]; then
                printf '%s\n' "${_atom}"
                break
            fi
        done
    done
    return 0
}
